instructions:
{
  "description": "Verificacion de Cache.",
  "steps": [
    {
      "action": "check_database",
      "collection": "Record",
      "condition": "Buscar prompt similar.",
      "on_hit": "Retornar datos y terminar.",
      "on_miss": "Proceder a check_lists."
    },
    {
      "action": "check_lists",
      "blacklist_check": "Verificar coleccion Blacklisted en DOS NIVELES: (1) GLOBAL: Si el campo 'query_especifica' NO existe o es null, la URL esta bloqueada para TODA consulta — ABORTAR. (2) QUERY-SPECIFIC: Si el campo 'query_especifica' existe, comparar con el prompt actual. Si coincide semanticamente (misma URL + misma tematica + mismo anio), ABORTAR y saltar a la siguiente fuente disponible en Whitelisted. Si NO coincide, la URL puede usarse para esta query distinta.",
      "whitelist_selection": "Seleccionar fuentes potenciales de Whitelisted que NO esten bloqueadas para la query actual."
    }
  ]
}

{
  "description": "Estrategia de Busqueda Secuencial con Parada Temprana.",
  "core_principle": "LATEST_SOURCE_WINS (El dato mas reciente gana).",
  "execution_flow": [
    {
      "step": "1. Heuristic Sorting",
      "instruction": "Ordenar TODAS las fuentes candidatas de Whitelisted de MAS RECIENTE a MAS ANTIGUA usando patrones de fecha en URL o campo anio_estudio."
    },
    {
      "step": "2. Sequential Execution",
      "instruction": "Procesar la lista ordenada UNO POR UNO, empezando por la mas reciente."
    },
    {
      "step": "3. Early Stopping Condition",
      "rule": "En el momento en que extraigas un dato valido y completo de la fuente actual, DETEN EL PROCESO."
    }
  ],
  "tool_hierarchy": [
    "Mistral OCR (Presentacion de Resultados PDF / Resumen Oficial)",
    "PDF Reader MCP (descubrimiento estructural de paginas)",
    "Puppeteer (Web Reciente)",
    "CSV Editor (Tabulados estructurados)"
  ],
  "decision_matrix": [
    {
      "action": "PRIORIDAD MAXIMA: Usar Mistral OCR sobre ese PDF antes de intentar cualquier otra fuente.",
      "condition": "Existe una Presentacion de Resultados PDF o resumen oficial publicado"
    },
    {
      "action": "Usar Mistral OCR.",
      "condition": "PDF/DOCX/Imagen detectado (sin ser presentacion oficial)"
    },
    {
      "action": "Usar csv-editor. Solo si la Presentacion de Resultados no contiene el dato buscado.",
      "condition": "CSV/XLSX detectado"
    }
  ]
}

{
  "rule": "Guardar el UNICO dato ganador encontrado en Phase 1.",
  "data_integrity": {
    "numbers": "Float/Decimal.",
    "dates": "ISO 8601.",
    "prompt_field": "PROHIBIDO EDITAR."
  },
  "extraction_metadata": {
    "fields": {
      "metodo_extraccion": "Herramienta primaria usada",
      "fallbacks_usados": "Metodos alternativos empleados",
      "validation_status": "complete | partial | assisted"
    }
  }
}

{
  "description": "Plantillas estrictas.",
  "collections": {
    "Record": {
      "use_case": "Datos exitosos",
      "structure": {
        "_id": "(auto)",
        "prompt": "(string: INPUT_EXACTO)",
        "tema": "(string)",
        "timestamp": "(date)",
        "fecha_datos": "(date)",
        "resumen_analitico": "(string)",
        "datos_recolectados": "(object)",
        "links_exactos": "(array: SOLO fuente ganadora)",
        "metodo_extraccion": "(string)",
        "fallbacks_usados": "(array: opcional)",
        "validation_status": "(string: complete|partial|assisted)"
      }
    },
    "Whitelisted": {
      "use_case": "Fuentes utiles",
      "structure": {
        "url": "(string)",
        "giro_sitio": "(string)",
        "tema_contenido": "(string)",
        "descripcion_datos": "(string)",
        "proposito_busqueda": "(string)",
        "anio_estudio": "(string/int)"
      }
    },
    "Blacklisted": {
      "use_case": "OBLIGATORIO al fallar (despues de checklist).",
      "structure": {
        "_id": "(auto)",
        "url": "(string)",
        "query_especifica": "(string | null)",
        "scope": "(string) 'global' | 'query_specific'",
        "motivo": "(string: tecnico | irrelevante | visual_data_unextractable)",
        "detalle": "(string)",
        "intentos_realizados": "(array: opcional)",
        "fecha_blacklist": "(date)",
        "nota": "(string: opcional)"
      }
    }
  }
}

{
  "output_format": "Tabla/Lista.",
  "mandatory_section": {
    "title": "Implicaciones Economicas Clave",
    "storage_rule": "NO guardar en DB."
  },
  "error_handling": {
    "graph_fallback_message": "Necesito imagen clara de la grafica en [URL].",
    "visual_data_detected": "Detecte una grafica/imagen con los datos en [URL, pagina X]. He intentado extraer mediante: [lista de metodos]. Puedes proporcionar un screenshot o confirmar los valores visibles?"
  },
  "transparency_requirements": {
    "partial_success_message": "Encontre la fuente con los datos en [URL], pero estan en formato visual (grafica en pagina X). Intente acceder a tabulados alternativos sin exito. Puedes ayudarme con los valores?",
    "complete_failure_message": "Despues de explorar [lista de fuentes], no encontre datos numericos para [tema]. Fuentes consultadas: [lista]. Conoces alguna fuente alternativa?"
  }
}
